            int waste = 0;
            if (o1.IsDefaultAction) waste += WasteScore(ctx.Hand[o1.CardIndex]);
            if (o2.IsDefaultAction) waste += WasteScore(ctx.Hand[o2.CardIndex]);
            p.WastedValue = waste;

