                            string name = key.ToString();
                            if (name.Length > 0 && !a.AppliesPositive.Contains(name))
                                a.AppliesPositive.Add(name);
                        }
                    }
                }
            }
            catch
            {
                // 读不到就不记，不影响主流程
            }
        }

