            var uppersBy = new List<List<ActionOption>>();   // 每张牌能填「上半位」的候选
            var lowersBy = new List<List<ActionOption>>();   // 每张牌能填「下半位」的候选
            for (int i = 0; i < n; i++)
            {
                uppersBy.Add(UpperOptions(ctx, i, atkCarrier));
                lowersBy.Add(LowerOptions(ctx, i, mvCarrier));
